"""Synthetic COBB-style EA888 WOT logs, generated by the MVEM.

Two purposes: (1) exercise/validate the ingestion+QA path before real logs arrive, and
(2) the seed of the synthetic-data generation we need for training. Output columns and
units mimic a COBB Accessport export so they round-trip through `ingest`.
"""

from __future__ import annotations

import numpy as np
import pandas as pd

from ..config import EA888_GEN3
from ..config.engine import EngineParams
from ..physics import OperatingPoint, simulate_wot
from ..physics.constants import N_REV_PER_CYCLE, P_ATM
from .units import PSI_TO_KPA

_PA_PER_PSI = PSI_TO_KPA * 1000.0


def _boost_psi(rpm: float) -> float:
    """Simple spool curve: ramp up, hold, mild top-end taper (psi gauge)."""
    spool = 21.0 * (1.0 - np.exp(-(max(rpm, 2000.0) - 2000.0) / 900.0))
    taper = max(0.0, (rpm - 5800.0) / 1000.0) * 2.0
    return float(np.clip(spool - taper, 0.0, 21.0))


def generate_cobb_wot_log(
    engine: EngineParams = EA888_GEN3,
    octane: float = 98.0,
    lam: float = 0.85,
    dt: float = 0.05,
    rpm_start: float = 2600.0,
    rpm_end: float = 6800.0,
    pull_s: float = 8.0,
    lead_s: float = 2.0,
    spark_offset_deg: float = 0.0,  # <0 simulates a conservative tune (timing left on table)
    seed: int = 0,
) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    rows: list[dict] = []
    t = 0.0
    afr_stoich = engine.afr_stoich

    def add(rpm, boost_psi, charge_c, pedal, gear, knock=0.0):
        nonlocal t
        p_im = P_ATM + boost_psi * _PA_PER_PSI
        op = OperatingPoint(rpm=rpm, p_im_pa=p_im, charge_temp_k=charge_c + 273.15, lam=lam, octane=octane)
        r = simulate_wot(op, engine)
        cps = (rpm / 60.0) / N_REV_PER_CYCLE
        airmass_g = r.m_dot_air / cps / engine.num_cylinders * 1000.0
        rows.append(
            {
                "Time": round(t, 3),
                "Engine Speed": round(rpm, 0),
                "Boost Pressure": round(boost_psi, 2),
                "Intake Manifold Pressure": round(p_im / _PA_PER_PSI, 2),
                "Charge Air Temp": round(charge_c, 1),
                "Intake Air Temp": round(charge_c - 8.0, 1),
                "Air Mass Intake Manifold Per Stroke": round(airmass_g, 4),
                "AFR": round(lam * afr_stoich + rng.normal(0, 0.05), 2),
                "AFR Set Point": round(lam * afr_stoich, 2),
                "Ignition Timing Final": round(max(2.0, r.spark_deg + spark_offset_deg), 1),
                "Knock Retard Cylinder 1": round(knock if rng.random() < 0.5 else 0.0, 1),
                "Knock Retard Cylinder 2": round(knock if rng.random() < 0.4 else 0.0, 1),
                "Knock Retard Cylinder 3": round(knock if rng.random() < 0.4 else 0.0, 1),
                "Knock Retard Cylinder 4": round(knock if rng.random() < 0.5 else 0.0, 1),
                "Intake Cam Position": round(12.0 + 6.0 * (rpm / 7000.0), 1),
                "Exhaust Cam Position": round(-5.0 - 4.0 * (rpm / 7000.0), 1),
                "Wastegate Valve Position": round(float(np.clip(boost_psi / 21.0 * 90.0, 0, 95)), 1),
                "Injection Time": round(1.0 + airmass_g * 1.4, 2),
                "Accel Pedal Position": round(pedal, 0),
                "Current Gear": gear,
            }
        )
        t += dt

    # idle / cruise lead-in (should be filtered out by WOT detection)
    for _ in range(int(lead_s / dt)):
        add(rpm=1500 + rng.normal(0, 25), boost_psi=0.0, charge_c=35.0, pedal=12, gear=3)

    # the WOT pull
    n = int(pull_s / dt)
    for i in range(n):
        frac = i / (n - 1)
        rpm = rpm_start + frac * (rpm_end - rpm_start)
        boost = _boost_psi(rpm)
        charge_c = 38.0 + frac * 14.0 + rng.normal(0, 0.4)
        op = OperatingPoint(rpm, P_ATM + boost * _PA_PER_PSI, charge_c + 273.15, lam=lam, octane=octane)
        r = simulate_wot(op, engine)
        knock = (
            float(max(0.0, rng.normal(0.8, 0.6)))
            if (r.knock_limited and r.knock_margin < 0.06 and spark_offset_deg > -1.5)
            else 0.0
        )
        add(rpm=rpm, boost_psi=boost, charge_c=charge_c, pedal=100, gear=3, knock=knock)

    return pd.DataFrame(rows)
